import {normalizePhone} from './community.mjs';
export function initSocial(c,h){const {$,state,req,button,element,toast,busy}=c;const rpc=h.rpc;
 const act=(api,action,payload={})=>rpc(api,{action,payload});
 const avatars=new Map();
 async function avatar(path,node){if(!path)return;try{let url=avatars.get(path);if(!url||url.until<Date.now()){const r=await req('/storage/v1/object/sign/profile-images/'+path.split('/').map(encodeURIComponent).join('/'),{method:'POST',body:{expiresIn:600}});url={src:'https://dlkykiducjimwehfhxfq.supabase.co/storage/v1'+r.signedURL,until:Date.now()+540000};avatars.set(path,url);}node.replaceChildren();const img=element('img');img.src=url.src;img.alt='صورة العرض';node.append(img);}catch{}}
 function personButton(p,fn){const b=button('',fn,'chat-contact');const pic=element('span',p.display_name?.slice(0,1)||'♙','avatar');b.append(pic,element('span',p.display_name));avatar(p.avatar_path,pic);return b;}
 const profile=$('profile-dialog');const pic=element('button','♙','avatar profile-picture');pic.type='button';pic.title='عرض صورة الحساب';profile.querySelector('h2').after(pic);const input=element('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.id='avatar-file';const fileLabel=element('label','تغيير صورة العرض');fileLabel.append(input);profile.querySelector('hr').before(fileLabel);pic.onclick=()=>{const img=pic.querySelector('img');if(img){const d=dialog('صورة العرض');const big=element('img');big.src=img.src;big.alt='صورة العرض';big.className='avatar-large';d.append(big);d.showModal();}};
 input.onchange=()=>busy(pic,async()=>{const file=input.files[0];if(!file)return;if(file.size>20*1024*1024)throw new Error('حجم الصورة يتجاوز 20 ميجابايت.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=canvas.height=512;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,512,512);const side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,512,512);bitmap.close();let blob;for(let q=.85;q>=.35;q-=.1){blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',q));if(blob?.size<=204800)break;}if(!blob||blob.size>204800)throw new Error('تعذر ضغط الصورة.');const path=state.user.id+'/'+crypto.randomUUID()+'.jpg';await req('/storage/v1/object/profile-images/'+path,{method:'POST',body:blob,raw:true,headers:{'Content-Type':'image/jpeg'}});try{await act('account_action','avatar',{path});}catch(e){await req('/storage/v1/object/profile-images',{method:'DELETE',body:{prefixes:[path]}}).catch(()=>{});throw e;}state.profile.avatar_path=path;await avatar(path,pic);toast('تم حفظ صورة العرض.');});
 const phoneForm=element('form');phoneForm.innerHTML='<h3>طلب تغيير الجوال</h3><label>رقم الجوال الجديد<input id="phone-new" type="tel" required></label><button class="secondary">إرسال طلب للمدير</button><div id="phone-own-list"></div>';profile.append(phoneForm);phoneForm.onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{await act('account_action','phone_request',{phone:normalizePhone($('phone-new').value)});phoneForm.reset();await ownPhones();toast('وصل طلب تغيير الجوال للمدير.');});};
 const emailForm=element('form');emailForm.innerHTML='<h3>تغيير البريد الإلكتروني</h3><label>البريد الجديد<input id="email-new" type="email" required autocomplete="email"></label><button class="secondary">إرسال تأكيد تغيير البريد</button><p class="muted">أكمل التأكيد من رسائل البريد. يبقى البريد الحالي حتى اكتمال التحقق.</p>';profile.append(emailForm);emailForm.onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{await req('/auth/v1/user?redirect_to='+encodeURIComponent(location.origin+'/'),{method:'PUT',body:{email:$('email-new').value.trim()}});emailForm.reset();toast('أُرسل طلب تأكيد تغيير البريد. راجع البريد القديم والجديد.');});};
 profile.append(button('▤ نشاطي في الأخبار',history,'secondary'));
 async function history(){const d=dialog('نشاطي في الأخبار');d.showModal();const data=await act('account_action','history');for(const [key,title]of[['posts','أخباري'],['comments','تعليقاتي'],['likes','إعجاباتي']]){d.append(element('h3',title));for(const row of data[key]||[]){const item=element('article',undefined,'activity-row');item.append(element('strong',row.title),element('p',row.body||new Date(row.created_at).toLocaleDateString('ar-SA')));d.append(item);}if(!data[key]?.length)d.append(element('p','لا توجد سجلات.','muted'));}}
 function dialog(title){const d=element('dialog');d.append(element('h2',title),button('✕ إغلاق',()=>{d.close();d.remove()},'dialog-close text-button'));document.body.append(d);return d;}
 async function viewMember(p){const data=await act('account_action','directory_profile',{member:p.id}),d=dialog(data.display_name),a=element('span','♙','avatar profile-picture');d.append(a,element('p',({admin:'مدير',journalist:'صحفي',member:'عضو'}[data.role])));await avatar(data.avatar_path,a);const img=a.querySelector('img');if(img){img.className='avatar-large';a.className='';}d.showModal();}
 async function ownPhones(){const rows=await act('account_action','phone_list');$('phone-own-list').replaceChildren();for(const r of rows.filter(x=>x.member_id===state.user.id))$('phone-own-list').append(element('p',r.new_phone+' — '+({pending:'بانتظار المدير',approved:'تمت الموافقة',rejected:'مرفوض'}[r.status])));}
 const controls=element('div',undefined,'post-actions');controls.append(button('＋ مجموعة',()=>createGroup('group'),'secondary'));const eventButton=button('◷ حدث محدد',()=>createGroup('event'),'secondary');eventButton.id='create-event';controls.append(eventButton);const groupInfo=button('ⓘ معلومات المحادثة',()=>groupDetails(h.currentGroup()),'secondary');groupInfo.id='group-info';groupInfo.hidden=true;controls.append(groupInfo);const memberInfo=button('♙ ملف العضو',()=>viewMember(h.currentPeer()),'secondary');memberInfo.hidden=true;controls.append(memberInfo);document.querySelector('.chat-layout aside').prepend(controls);const groupsBox=element('div');groupsBox.id='chat-groups';document.querySelector('.chat-layout aside').append(element('h3','المجموعات والأحداث'),groupsBox);
 let groups=[];
 async function loadGroups(){groups=await act('group_action','list');groupsBox.replaceChildren();for(const g of groups){const b=button('',()=>h.openGroup(g),'chat-contact');b.append(element('span',g.kind==='event'?'◷':'♧','avatar'),element('span',g.title));if(g.kind==='event')b.append(element('small',(g.open_now?'الحدث جارٍ':'الحدث محدد بموعد')+' · '+new Date(g.starts_at).toLocaleString('ar-SA')));groupsBox.append(b);}eventButton.hidden=state.profile.role!=='admin';groupInfo.hidden=!h.currentGroup();memberInfo.hidden=!h.currentPeer();return groups;}
 async function selectionUI(d,onSelect){const search=element('input');search.placeholder='بحث بالاسم أو رقم الجوال';const results=element('div');d.append(search,results);let timer,requestNo=0;search.oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>busy(search,async()=>{const term=search.value.trim();if(term.length<2){results.replaceChildren();return;}const version=++requestNo;let value=term;try{value=normalizePhone(term);}catch{}const rows=await rpc('chat_search',{term:value});if(version!==requestNo)return;results.replaceChildren();for(const p of rows)results.append(personButton(p,()=>onSelect(p)));}),350);};}
 async function createGroup(kind){if(kind==='group'&&state.profile.role!=='admin'&&!state.settings.allow_groups)throw new Error('إنشاء المجموعات موقوف من المدير.');const d=dialog(kind==='event'?'إنشاء حدث لأشخاص محددين':'إنشاء مجموعة');const form=element('form');form.innerHTML='<label>عنوان المحادثة<input name="title" required minlength="3" maxlength="100"></label>'+(kind==='event'?'<label>بداية الحدث<input name="start" type="datetime-local" required></label><label>نهاية الحدث<input name="end" type="datetime-local" required></label>':'');d.append(form);const chosen=new Map,selected=element('div');d.append(selected);await selectionUI(d,p=>{chosen.set(p.id,p);selected.replaceChildren();for(const p of chosen.values())selected.append(button('✕ '+p.display_name,()=>{chosen.delete(p.id);selected.replaceChildren();for(const v of chosen.values())selected.append(element('p',v.display_name));}));});const save=element('button','إنشاء','primary');form.append(save);form.onsubmit=e=>{e.preventDefault();busy(save,async()=>{const payload={title:form.elements.title.value.trim(),kind,members:[...chosen.keys()]};if(kind==='event'){payload.starts_at=new Date(form.elements.start.value).toISOString();payload.ends_at=new Date(form.elements.end.value).toISOString();if(payload.ends_at<=payload.starts_at)throw new Error('النهاية يجب أن تكون بعد البداية.');}const id=await act('group_action','create',payload);d.close();d.remove();await loadGroups();const g=groups.find(x=>x.id===id);await h.openGroup(g);toast('تم إنشاء المحادثة.');});};d.showModal();}
 async function groupDetails(id){if(!id)return;const g=groups.find(x=>x.id===id);const d=dialog(g?.title||'المجموعة');d.showModal();const list=element('div');d.append(list);async function refresh(){const rows=await act('group_action','members',{id});list.replaceChildren();for(const p of rows){const row=element('div',undefined,'group-person');row.append(personButton(p,()=>viewMember(p)));if((g.owner_id===state.user.id||state.profile.role==='admin')&&p.id!==g.owner_id)row.append(button('إزالة',async()=>{if(!confirm('إزالة العضو من المجموعة؟'))return;await act('group_action','remove',{id,member:p.id});await refresh();}));list.append(row);}}await refresh();if(g.owner_id===state.user.id||state.profile.role==='admin')await selectionUI(d,async p=>{await act('group_action','add',{id,member:p.id});await refresh();});if(g.owner_id!==state.user.id)d.append(button('مغادرة',async()=>{await act('group_action','leave',{id});d.close();d.remove();await h.clearGroup();}));}
 const adminRequests=element('div');adminRequests.id='phone-admin-list';$('settings-section').append(element('h3','طلبات تغيير الجوال'),adminRequests);
 async function adminPhones(){const rows=await act('account_action','phone_list');adminRequests.replaceChildren();for(const r of rows.filter(x=>x.status==='pending')){const card=element('article',undefined,'activity-row');card.append(element('h4',r.display_name),element('p',(r.current_phone||'غير محدد')+' ← '+r.new_phone),button('اعتماد الجوال',async()=>{await act('account_action','phone_approve',{id:r.id});await adminPhones();}),button('رفض',async()=>{await act('account_action','phone_reject',{id:r.id});await adminPhones();}));adminRequests.append(card);}if(!adminRequests.children.length)adminRequests.append(element('p','لا توجد طلبات معلّقة.'));}
 const endorsementButton=button('✓ التعريف بالأعضاء',openEndorsements,'secondary');endorsementButton.id='endorsement-open';$('profile-open').after(endorsementButton);const profileEndorsement=button('✓ طلبات التعريف بالأعضاء',openEndorsements,'secondary');profileEndorsement.hidden=true;profile.append(profileEndorsement);
 async function openEndorsements(){const d=dialog('التعريف بالأعضاء');d.showModal();const active=state.profile.status==='active';d.append(element('p',active?'ابحث عن عضو ينتظر الاعتماد لتأكيد معرفتك به.':'اختر عضوًا معتمدًا يعرفك ليوافق على تعريفك.'));const search=element('input');search.placeholder=active?'اسم العضو أو جواله أو بريده':'اسم المعرّف أو رقم جواله';const results=element('div'),requests=element('div');d.append(search,results,element('h3','طلبات التعريف والإشعارات'),requests);let timer;search.oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>busy(search,async()=>{let term=search.value.trim();if(term.length<3)return;try{term=normalizePhone(term);}catch{}const rows=await act('endorse_action',active?'search':'sponsors',{term});results.replaceChildren();for(const p of rows)results.append(personButton(p,async()=>{if(!confirm(active?'إرسال طلب تعريف لهذا العضو؟ ستراجع بياناته قبل اعتمادك.':'إرسال بيانات التسجيل إلى هذا المعرّف لمراجعتها؟'))return;await act('endorse_action',active?'offer':'request',{member:p.id});await refresh();toast('أُرسل إشعار داخل التطبيق.');}));if(!rows.length)results.append(element('p','لا توجد نتائج.'));}),350);};async function refresh(){const rows=await act('endorse_action','list');requests.replaceChildren();for(const r of rows){const card=element('article',undefined,'activity-row');card.append(element('h4',r.display_name+' — المُعرّف: '+r.sponsor_name),element('p',({pending:'بانتظار الموافقة',approved:'تم التعريف والتفعيل',rejected:'مرفوض'}[r.status])));if(r.sponsor_id===state.user.id&&r.status==='pending'){card.append(element('p','الاسم الرباعي: '+r.full_name),element('p','الجوال: '+(r.phone||'غير مكتمل')),element('p','البريد: '+r.email+(r.email_confirmed?' (مؤكد)':' (غير مؤكد)')),element('p','الجنس: '+({male:'ذكر',female:'أنثى'}[r.gender]||'غير محدد')),element('p','المعرّف المسجل: '+(r.reference_name||'—')+' / '+(r.relationship||'—')),button('أعرف هذا العضو وأوافق على تفعيله',async()=>{if(!confirm('أؤكد معرفتي الشخصية بهذا العضو وصحة نسبه للعائلة، وأوافق على تفعيل حسابه.'))return;await act('endorse_action','approve',{id:r.id,confirm:true});await refresh();await notifications();toast('تم تفعيل العضو بعد تأكيد البريد.');}),button('لا أعرفه — رفض',async()=>{await act('endorse_action','reject',{id:r.id});await refresh();await notifications();}));}requests.append(card);}}await refresh();}
 async function notifications(){if(!state.user)return;const own=await rpc('profile_get');endorsementButton.hidden=profileEndorsement.hidden=!own.endorsements_enabled;if(!own.endorsements_enabled)return;const rows=await act('endorse_action','list'),pending=rows.filter(r=>r.sponsor_id===state.user.id&&r.status==='pending').length;endorsementButton.textContent='✓ التعريف بالأعضاء'+(pending?' · '+pending:'');}
 setInterval(()=>{if(state.user&&!document.hidden)notifications().catch(()=>{});},30000);
 return {personButton,avatar,viewMember,loadGroups,async profile(p){await avatar(p.avatar_path,pic);$('profile-phone').readOnly=!!p.phone;await ownPhones();},async loaded(){await notifications();},async settings(){await adminPhones();},reset(){avatars.clear();groups=[];groupsBox.replaceChildren();endorsementButton.hidden=true;}};
}
